import React, { useMemo } from "react";
let BoldReportViewerComponent: any;
try {
  BoldReportViewerComponent = require("@boldreports/react-reporting-components").BoldReportViewerComponent;
} catch (err) {
  console.warn("BoldReports module not found.");
}

interface BoldReportProps {
  apiUrl: string;
  reportName: string;
  tenantId: string;
}

export const BoldReport: React.FC<BoldReportProps> = ({ apiUrl, reportName, tenantId }) => {
  const start = new Date().toISOString();
  const end = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString();
  const clientTime = new Date().toISOString();

  const reportParams = useMemo(() => [
    { name: "TenantId", value: tenantId },
    { name: "StartDate", value: start },
    { name: "EndDate", value: end },
    { name: "ReportGeneratedOn", value: clientTime },
  ], [tenantId, start, end, clientTime]);

  if (!BoldReportViewerComponent) return <div>Error loading BoldReportViewerComponent</div>;

  return (
    <div style={{ height: "600px", width: "100%" }}>
      <BoldReportViewerComponent
        id="reportViewer"
        reportServiceUrl={apiUrl}
        reportPath={reportName}
        parameters={reportParams}
        toolbarSettings={{ showToolbar: true }}
        height="100%"
      />
    </div>
  );
};
